// Time-mask resolution is independent of full-resolution window content.
static constexpr int kPaintBrushSize = 3;
static constexpr int kPaintBrushMaskSize = 1024;
struct PaintBrushSpan { uint16_t first; uint16_t last; };
static_assert(sizeof(PaintBrushSpan) == 4 && kPaintBrushMaskSize % 8 == 0);
static uint32_t PaintBrushRowCapacity(const uint16_t* row) {
    // Every above-threshold run contains a local maximum or an endpoint.
    // Ignore plateaus when counting turns. Two endpoint slots plus all
    // interior maxima bound every possible threshold, without a dense grid
    // of worst-case scratch spans per animation.
    uint32_t capacity = 2;
    int direction = 0;
    for (int x = 1; x < kPaintBrushMaskSize; ++x) {
        const int next = (row[x] > row[x - 1]) - (row[x] < row[x - 1]);
        if (direction > 0 && next < 0) ++capacity;
        if (next) direction = next;
    }
    return capacity;
}
struct PaintBrushMask {
    std::span<const uint16_t> times;
    std::array<uint32_t, kPaintBrushMaskSize + 1> spanOffsets{};
    std::vector<uint16_t> localTimes;
    HANDLE sharedMapping{};
    const void* sharedView{};
    bool sharedBuilt = false;
    ~PaintBrushMask() {
        if (sharedView) UnmapViewOfFile(sharedView);
        if (sharedMapping) CloseHandle(sharedMapping);
    }
};
// END PAINT BRUSH TYPES
