template <typename Effect, size_t EntryCount>
static Effect ParseEffectSetting(
    PCWSTR value, const EffectSettingEntry<Effect> (&entries)[EntryCount],
    Effect fallback) {
    if (value) {
        for (const auto& entry : entries) {
            if (entry.name == value) return entry.effect;
        }
    }
    return fallback;
}

static CloseEffect ParseCloseEffect(PCWSTR value) {
    return ParseEffectSetting(value, kCloseEffectSettings,
                              CloseEffect::Thanos);
}

static MinRestoreEffect ParseMinRestoreEffect(PCWSTR value) {
    return ParseEffectSetting(value, kMinRestoreEffectSettings,
                              MinRestoreEffect::Genie);
}

static_assert(std::size(kCloseEffectSettings) == kCloseEffectCount);
static_assert(std::size(kMinRestoreEffectSettings) == kMinRestoreEffectCount);

static constexpr bool NeedsBootstrapFrame(MinRestoreEffect effect) {
    switch (effect) {
        case MinRestoreEffect::Ink:
        case MinRestoreEffect::Scorch:
        case MinRestoreEffect::Splinter:
        case MinRestoreEffect::Mirage:
        case MinRestoreEffect::Stipple:
        case MinRestoreEffect::Swell:
        case MinRestoreEffect::InkwellDrop:
        case MinRestoreEffect::PlasmaFlow:
        case MinRestoreEffect::Morph:
        case MinRestoreEffect::Smoke:
        case MinRestoreEffect::Apparition:
        case MinRestoreEffect::Hexagon:
            return true;

        case MinRestoreEffect::Genie:
        case MinRestoreEffect::MacOSGenie:
        case MinRestoreEffect::MacOSSuck:
        case MinRestoreEffect::Windows10:
        case MinRestoreEffect::Glide:
        case MinRestoreEffect::Count:
            return false;
    }
    return false;
}

static constexpr bool NeedsBootstrapFrame(CloseEffect effect,
                                          bool usingGpuBackend) {
    switch (effect) {
        case CloseEffect::Perlin:
            return usingGpuBackend;

        case CloseEffect::Glitch:
        case CloseEffect::Crt:
        case CloseEffect::Melt:
        case CloseEffect::BrokenGlass:
        case CloseEffect::Trex:
        case CloseEffect::PaintBrush:
            return true;

        case CloseEffect::Shatter:
        case CloseEffect::Thanos:
        case CloseEffect::Glide:
        case CloseEffect::Count:
            return false;
    }
    return false;
}

